1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: empty and single items (base premiums + fee) ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("single sword (plain, new customer) → 100 G base + 10 G first insurance + 5 G fee = 115 G");
15	  it.todo("single amulet (plain, new customer) → 60 G base + 6 G first insurance + 5 G fee = 71 G");
16	  it.todo("single staff (plain, new customer) → 80 G base + 8 G first insurance + 5 G fee = 93 G");
17	  it.todo("single potion (plain, new customer) → 40 G base + 4 G first insurance + 5 G fee = 49 G");
18	  it.todo("single rune (component) → 25 G base + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
19	
20	  // --- Building block of 3 alike components ---
21	  it.todo("2 runes → 50 G base premium");
22	  it.todo("3 runes → 60 G base premium (block applies)");
23	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
24	  it.todo("7 runes → 175 G base premium");
25	
26	  // --- "Alike" components means same type ---
27	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
28	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
29	
30	  // --- Item-specific modifiers ---
31	  it.todo("cursed sword adds 50 % of that item's base premium (100 G → +50 G)");
32	  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge (100 G → +30 G)");
33	  it.todo("sword with enchantment 4 has no high-enchantment surcharge");
34	  it.todo("cursed sword with enchantment 5 gets both surcharges (+50 G and +30 G)");
35	
36	  // --- Modifier scope on multi-item policies ---
37	  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (not 50 % of policy total) → 210 G before further modifiers and fee");
38	
39	  // --- Policy-wide modifiers ---
40	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount on the policy base premium");
41	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
42	  it.todo("first insurance surcharge of 10 % applies to every quote's items");
43	  it.todo("second quote in a scenario receives a 15 % follow-up contract discount");
44	
45	  // --- Rounding in MHPCO's favour ---
46	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
47	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
48	
49	  // --- Integration examples ---
50	  it.todo("newcomer (0 years) with a cursed steel sword enchantment 3 → premium 165 G");
51	  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 → premium 160 G");
52	
53	  // --- Claim: standard reimbursement ---
54	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
55	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
56	
57	  // --- Claim: special clauses ---
58	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
59	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
60	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
61	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
62	
63	  // --- Claim: deductible per damage event ---
64	  it.todo("dragon attack damaging sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");
65	
66	  // --- Claim: cap ---
67	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
68	  it.todo("a cursed sword → cap 2000 G based on the unmodified insurance value");
69	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects premium only)");
70	  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
71	  it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");
72	
73	  // --- Multiple items of the same type ---
74	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
75	  it.todo("two sword damage entries against a two-sword policy → each is a separate damage with its own deductible");
76	  it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → the claim is rejected");
77	
78	  // --- Error cases ---
79	  it.todo("quote with an unknown item type (broomstick) → error, no results");
80	  it.todo("claim damaging an amulet when only a sword is insured → error");
81	  it.todo("claim with a damage entry of an unknown item type → error");
82	  it.todo("claim with a damage entry amount of -200 → error");
83	
84	  // --- CLI ---
85	  it.todo("CLI reads a scenario from stdin and writes {results:[...]} to stdout");
86	  it.todo("CLI exits with a non-zero status code and writes to stderr on an invalid scenario");
87	});
